import XCTest
@testable import AetherCore

/// A fetcher over `total` generated bytes (byte `i` is `i % 251`) that can be scripted per range and attempt.
private final class FakeRangeFetcher: RelayRangeFetcher, @unchecked Sendable {
    enum Outcome {
        case ok
        case fail(Error)
        case short
        case hang
    }

    let total: Int64
    var probeError: Error?
    var reportsLength = true
    var script: (@Sendable (ClosedRange<Int64>, Int) -> Outcome)?

    private let lock = NSLock()
    private var _ranges: [ClosedRange<Int64>] = []
    private var _attempts: [Int64: Int] = [:]
    private var _inFlight = 0
    private var _maxInFlight = 0
    private var _cancelled = 0
    private var _invalidated = false

    init(total: Int64 = 1000) {
        self.total = total
    }

    var ranges: [ClosedRange<Int64>] { return locked { _ranges } }
    var sortedRanges: [ClosedRange<Int64>] { return ranges.sorted { $0.lowerBound < $1.lowerBound } }
    var maxInFlight: Int { return locked { _maxInFlight } }
    var cancelledFetches: Int { return locked { _cancelled } }
    var invalidated: Bool { return locked { _invalidated } }
    func attempts(startingAt start: Int64) -> Int { return locked { _attempts[start] ?? 0 } }

    private func locked<T>(_ body: () -> T) -> T {
        lock.lock()
        defer { lock.unlock() }
        return body()
    }

    func probe() async throws -> RelayResource {
        if let error = probeError { throw error }
        // The type the upstream claims is not what the receiver is told.
        return RelayResource(contentType: "text/html", length: reportsLength ? total : nil, acceptsRanges: true)
    }

    func fetch(_ range: ClosedRange<Int64>) async throws -> Data {
        let attempt: Int = locked {
            _ranges.append(range)
            _attempts[range.lowerBound, default: 0] += 1
            _inFlight += 1
            _maxInFlight = max(_maxInFlight, _inFlight)
            return _attempts[range.lowerBound] ?? 1
        }
        defer { locked { _inFlight -= 1 } }
        switch script?(range, attempt) ?? .ok {
        case .ok:
            _ = try? await Task.sleep(nanoseconds: 2_000_000)
            return MemoryRelaySource.expected(range)
        case .fail(let error):
            throw error
        case .short:
            return MemoryRelaySource.expected(range.lowerBound...(range.upperBound - 1))
        case .hang:
            do {
                try await Task.sleep(nanoseconds: 30_000_000_000)
            } catch {
                locked { _cancelled += 1 }
                throw error
            }
            return MemoryRelaySource.expected(range)
        }
    }

    func invalidate() {
        locked { _invalidated = true }
    }
}

private final class DoubleLog: @unchecked Sendable {
    private let lock = NSLock()
    private var items: [Double] = []

    func add(_ value: Double) {
        lock.lock()
        items.append(value)
        lock.unlock()
    }

    var values: [Double] {
        lock.lock()
        defer { lock.unlock() }
        return items
    }
}

private final class IntLog: @unchecked Sendable {
    private let lock = NSLock()
    private var items: [Int] = []

    func add(_ value: Int) {
        lock.lock()
        items.append(value)
        lock.unlock()
    }

    var values: [Int] {
        lock.lock()
        defer { lock.unlock() }
        return items
    }
}

final class HTTPRangeSourceTests: XCTestCase {
    private let sleeps = DoubleLog()
    private let rejections = IntLog()

    private func make(_ fetcher: FakeRangeFetcher, window: Int = 300) -> HTTPRangeSource {
        var limits = RelayLimits()
        limits.windowSize = window
        let sleeps = self.sleeps
        let rejections = self.rejections
        return HTTPRangeSource(leaf: "video.mkv", contentType: "video/x-matroska", fetcher: fetcher, limits: limits,
                               sleep: { sleeps.add($0) }, onUpstreamRejected: { rejections.add($0) })
    }

    private func drain(_ reader: RelayBodyReader) async throws -> Data {
        var all = Data()
        while let chunk = try await reader.next() { all.append(chunk) }
        return all
    }

    private func waitUntil(_ timeout: TimeInterval = 3, _ condition: () -> Bool) async -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while Date() < deadline {
            if condition() { return true }
            _ = try? await Task.sleep(nanoseconds: 5_000_000)
        }
        return condition()
    }

    // MARK: Preparing

    func testPrepareLearnsTheSizeAndKeepsTheAppsContentType() async throws {
        let source = make(FakeRangeFetcher())
        let resource = try await source.prepare()
        XCTAssertEqual(resource, RelayResource(contentType: "video/x-matroska", length: 1000, acceptsRanges: true))
        let again = try await source.resource(named: "video.mkv")
        XCTAssertEqual(again, resource)
    }

    func testASourceWithoutRangesIsRefusedAtPrepare() async {
        let fetcher = FakeRangeFetcher()
        fetcher.probeError = RelayError.upstreamNoRanges
        do {
            try await make(fetcher).prepare()
            XCTFail("expected a failure")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamNoRanges)
        }
        let unknown = FakeRangeFetcher()
        unknown.reportsLength = false
        do {
            try await make(unknown).prepare()
            XCTFail("an unknown size cannot be served in ranges")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamNoRanges)
        }
    }

    func testNothingIsServedBeforePrepareOrUnderAnotherName() async throws {
        let source = make(FakeRangeFetcher())
        do {
            _ = try await source.resource(named: "video.mkv")
            XCTFail("not prepared")
        } catch {
            XCTAssertEqual(error as? RelayError, .notFound)
        }
        try await source.prepare()
        do {
            _ = try await source.open("other.mkv", range: nil)
            XCTFail("wrong name")
        } catch {
            XCTAssertEqual(error as? RelayError, .notFound)
        }
    }

    // MARK: Reading

    func testTheWholeFileIsReadInWindows() async throws {
        let fetcher = FakeRangeFetcher()
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        let data = try await drain(reader)
        XCTAssertEqual(data, MemoryRelaySource.expected(0...999))
        XCTAssertEqual(fetcher.sortedRanges, [0...299, 300...599, 600...899, 900...999])
    }

    func testARangeStartsItsWindowsAtItsOwnStart() async throws {
        let fetcher = FakeRangeFetcher()
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: 250...749)
        let data = try await drain(reader)
        XCTAssertEqual(data, MemoryRelaySource.expected(250...749))
        XCTAssertEqual(fetcher.sortedRanges, [250...549, 550...749])
    }

    func testAnExactMultipleOfTheWindowAndAnEmptyFile() async throws {
        let exact = FakeRangeFetcher(total: 600)
        let source = make(exact)
        try await source.prepare()
        let data = try await drain(try await source.open("video.mkv", range: nil))
        XCTAssertEqual(data, MemoryRelaySource.expected(0...599))
        XCTAssertEqual(exact.sortedRanges, [0...299, 300...599])

        let empty = FakeRangeFetcher(total: 0)
        let emptySource = make(empty)
        try await emptySource.prepare()
        let nothing = try await drain(try await emptySource.open("video.mkv", range: nil))
        XCTAssertTrue(nothing.isEmpty)
        XCTAssertTrue(empty.ranges.isEmpty)
    }

    func testARangePastTheEndIsRefusedBeforeAnyRequest() async throws {
        let fetcher = FakeRangeFetcher()
        let source = make(fetcher)
        try await source.prepare()
        do {
            _ = try await source.open("video.mkv", range: 900...1000)
            XCTFail("expected a failure")
        } catch {
            XCTAssertEqual(error as? RelayError, .rangeNotSatisfiable(total: 1000))
        }
        XCTAssertTrue(fetcher.ranges.isEmpty)
    }

    func testTheNextWindowIsAlreadyRequestedAndNoMoreThanTwoRunAtOnce() async throws {
        let fetcher = FakeRangeFetcher()
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        let secondRequested = await waitUntil { fetcher.ranges.contains(300...599) }
        XCTAssertTrue(secondRequested, "the second window should be fetched while the first is being sent")
        _ = try await drain(reader)
        XCTAssertLessThanOrEqual(fetcher.maxInFlight, 2)
    }

    // MARK: Cancelling

    func testCancellingStopsTheWindowInFlight() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { range, _ in range.lowerBound >= 300 ? .hang : .ok }
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        let started = await waitUntil { fetcher.ranges.contains(300...599) }
        XCTAssertTrue(started)
        reader.cancel()
        let stopped = await waitUntil { fetcher.cancelledFetches == 1 }
        XCTAssertTrue(stopped, "the pending request should have been cancelled")
        let after = try await reader.next()
        XCTAssertNil(after)
    }

    func testClosingTheSourceCancelsItsReadersAndRefusesNewOnes() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { range, _ in range.lowerBound >= 300 ? .hang : .ok }
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        _ = await waitUntil { fetcher.ranges.contains(300...599) }
        source.close()
        XCTAssertTrue(fetcher.invalidated)
        let stopped = await waitUntil { fetcher.cancelledFetches == 1 }
        XCTAssertTrue(stopped)
        let after = try await reader.next()
        XCTAssertNil(after)
        do {
            _ = try await source.open("video.mkv", range: nil)
            XCTFail("a closed source serves nothing")
        } catch {
            XCTAssertEqual(error as? RelayError, .notFound)
        }
    }

    // MARK: Failures

    func testATemporaryFailureIsRetriedOnce() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { range, attempt in
            (range.lowerBound == 300 && attempt == 1) ? .fail(RelayError.upstreamUnreachable(code: -1005)) : .ok
        }
        let source = make(fetcher)
        try await source.prepare()
        let data = try await drain(try await source.open("video.mkv", range: nil))
        XCTAssertEqual(data, MemoryRelaySource.expected(0...999))
        XCTAssertEqual(sleeps.values, [RelayLimits.standard.retryDelay])
        XCTAssertEqual(fetcher.attempts(startingAt: 300), 2)
        XCTAssertTrue(rejections.values.isEmpty)
    }

    func testAServerErrorIsRetriedOnceThenReported() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { range, _ in range.lowerBound == 300 ? .fail(RelayError.upstreamRejected(status: 503)) : .ok }
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        do {
            _ = try await drain(reader)
            XCTFail("expected a failure")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamRejected(status: 503))
        }
        XCTAssertEqual(fetcher.attempts(startingAt: 300), 2)
        XCTAssertEqual(sleeps.values.count, 1)
        XCTAssertTrue(rejections.values.isEmpty, "a 503 is not a revoked link")
    }

    func testARefusedLinkIsNotRetriedAndIsReported() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { range, _ in range.lowerBound == 0 ? .fail(RelayError.upstreamRejected(status: 403)) : .ok }
        let source = make(fetcher)
        try await source.prepare()
        do {
            _ = try await source.open("video.mkv", range: nil)
            XCTFail("a dead link must fail at open, before any status is promised")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamRejected(status: 403))
        }
        XCTAssertEqual(fetcher.attempts(startingAt: 0), 1)
        XCTAssertTrue(sleeps.values.isEmpty)
        XCTAssertEqual(rejections.values, [403])
    }

    func testALinkThatDiesMidwayFailsFromNextAfterTheGoodWindows() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { range, _ in range.lowerBound == 600 ? .fail(RelayError.upstreamRejected(status: 403)) : .ok }
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        let first = try await reader.next()
        let second = try await reader.next()
        XCTAssertEqual(first, MemoryRelaySource.expected(0...299))
        XCTAssertEqual(second, MemoryRelaySource.expected(300...599))
        do {
            _ = try await reader.next()
            XCTFail("expected a failure")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamRejected(status: 403))
        }
        XCTAssertEqual(rejections.values, [403])
        let after = try await reader.next()
        XCTAssertNil(after, "a failed reader stays finished")
    }

    func testAShortAnswerIsABadRange() async throws {
        let fetcher = FakeRangeFetcher()
        fetcher.script = { _, _ in .short }
        let source = make(fetcher)
        try await source.prepare()
        do {
            _ = try await source.open("video.mkv", range: nil)
            XCTFail("expected a failure")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamBadRange)
        }
    }

    // MARK: Errors never carry an address

    func testNetworkErrorsAreReducedToTheirCode() {
        let error = URLError(.cannotFindHost, userInfo: [NSURLErrorFailingURLStringErrorKey: "https://x.test/f?key=SECRET"])
        let mapped = RelayError.mapping(error)
        XCTAssertEqual(mapped, .upstreamUnreachable(code: -1003))
        for text in [String(describing: mapped), String(reflecting: mapped), "\(mapped)"] {
            XCTAssertFalse(text.contains("SECRET"))
            XCTAssertFalse(text.contains("x.test"))
        }
        XCTAssertEqual(RelayError.mapping(RelayError.upstreamNoRanges), .upstreamNoRanges)
        struct Odd: Error { let secret = "SECRET" }
        XCTAssertEqual(RelayError.mapping(Odd()), .upstreamUnreachable(code: -1))
    }

    func testANetworkErrorMidBodyReachesTheReaderAsACodeOnly() async throws {
        let fetcher = FakeRangeFetcher()
        let urlError = URLError(.cannotFindHost, userInfo: [NSURLErrorFailingURLStringErrorKey: "https://x.test/f?key=SECRET"])
        fetcher.script = { range, _ in range.lowerBound == 300 ? .fail(urlError) : .ok }
        let source = make(fetcher)
        try await source.prepare()
        let reader = try await source.open("video.mkv", range: nil)
        do {
            _ = try await drain(reader)
            XCTFail("expected a failure")
        } catch {
            XCTAssertEqual(error as? RelayError, .upstreamUnreachable(code: -1003))
            XCTAssertFalse("\(error)".contains("SECRET"))
            XCTAssertFalse(String(reflecting: error).contains("x.test"))
        }
        XCTAssertEqual(fetcher.attempts(startingAt: 300), 2, "a lost connection is tried once more")
    }
}
